window.MATHS_DATA={"version":1,"exam":"Tuesday 24 November 2026","topics":["Arithmetic operations with algebra","Multiply a single term over a bracket","Substitute integers into expressions","Factorise by taking out the HCF","Recognise when an expression is not factorised completely","Construct and solve equations","Find an unknown that is not the subject of a formula","Laws of indices with numbers","Simplify expressions in index notation","Simplify expressions with brackets and powers","Construct and solve equations from geometrical information","Laws of indices","Area of parallelograms and triangles","Area of a trapezium","Area of parallelograms, triangles and trapezia","Volume of cuboids and cubes","Surface area of cuboids","Surface area of shapes made from cuboids","Convert between metric measures of volume and capacity","Volume, surface area and capacity"],"days":[{"id":1,"title":"Day 1 · Algebra basics","date":"Wed 18 Nov"},{"id":2,"title":"Day 2 · Factorising, equations & formulae","date":"Thu 19 Nov"},{"id":3,"title":"Day 3 · Indices & equations from shapes","date":"Fri 20 Nov"},{"id":4,"title":"Day 4 · Area of 2D shapes","date":"Sat 21 Nov"},{"id":5,"title":"Day 5 · Surface area, volume & capacity","date":"Sun 22 Nov"},{"id":6,"title":"Mock test","date":"Mon 23 Nov"},{"id":0,"title":"Extra practice bank","date":"Any day"}],"questions":[{"id":"m001","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 3a + 5b - a + 2b","a":"2a + 7b","alt":["2a+7b"],"ex":"Collect like terms: 3a - a = 2a; 5b + 2b = 7b. Answer: 2a + 7b."},{"id":"m002","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 7x - 2y + 3x + 6y","a":"10x + 4y","alt":["10x+4y"],"ex":"Collect like terms: 7x + 3x = 10x; -2y + 6y = 4y. Answer: 10x + 4y."},{"id":"m003","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 4p + 9 - p - 12","a":"3p - 3","alt":["3p-3"],"ex":"Collect like terms: 4p - p = 3p; 9 - 12 = -3. Answer: 3p - 3."},{"id":"m004","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 2a + 3b - 5a - 7b","a":"-3a - 4b","alt":["-3a-4b"],"ex":"Collect like terms: 2a - 5a = -3a; 3b - 7b = -4b. Answer: -3a - 4b."},{"id":"m005","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 5m^2 + 2m - 3m^2 + 4m","a":"2m^2 + 6m","alt":["2m^2+6m","2m² + 6m"],"ex":"Collect like terms: 5m^2 - 3m^2 = 2m^2; 2m + 4m = 6m. Answer: 2m^2 + 6m."},{"id":"m006","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 6xy + 2x - 4xy + 5x","a":"2xy + 7x","alt":["2xy+7x"],"ex":"Collect like terms: 6xy - 4xy = 2xy; 2x + 5x = 7x. Answer: 2xy + 7x."},{"id":"m007","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 8t - 3 + 2t^2 - 5t + 7","a":"2t^2 + 3t + 4","alt":["2t^2+3t+4","2t² + 3t + 4"],"ex":"Collect like terms: 8t - 5t = 3t; -3 + 7 = 4. Answer: 2t^2 + 3t + 4."},{"id":"m008","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 3x^2 + 4x - x^2 - 9x + 2","a":"2x^2 - 5x + 2","alt":["2x^2-5x+2","2x² - 5x + 2"],"ex":"Collect like terms: 3x^2 - x^2 = 2x^2; 4x - 9x = -5x. Answer: 2x^2 - 5x + 2."},{"id":"m009","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 3a × 4b","a":"12ab","alt":[],"ex":"Multiply the numbers: 3 × 4 = 12. Multiply the letters (same letter: add the powers): a × b = ab. Answer: 12ab."},{"id":"m010","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 5x × 2x","a":"10x^2","alt":["10x²"],"ex":"Multiply the numbers: 5 × 2 = 10. Multiply the letters (same letter: add the powers): x × x = x^2. Answer: 10x^2."},{"id":"m011","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify -2p × 6q","a":"-12pq","alt":[],"ex":"Multiply the numbers: (-2) × 6 = -12. Multiply the letters (same letter: add the powers): p × q = pq. Answer: -12pq."},{"id":"m012","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 4ab × 3a","a":"12a^2b","alt":["12a²b"],"ex":"Multiply the numbers: 4 × 3 = 12. Multiply the letters (same letter: add the powers): ab × a = a^2b. Answer: 12a^2b."},{"id":"m013","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify -3x × -5xy","a":"15x^2y","alt":["15x²y"],"ex":"Multiply the numbers: (-3) × (-5) = 15. Multiply the letters (same letter: add the powers): x × xy = x^2y. Answer: 15x^2y."},{"id":"m014","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 2a^2 × 7a","a":"14a^3","alt":["14a³"],"ex":"Multiply the numbers: 2 × 7 = 14. Multiply the letters (same letter: add the powers): a^2 × a = a^3. Answer: 14a^3."},{"id":"m015","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 12xy ÷ 4y","a":"3x","alt":[],"ex":"Divide the numbers: 12 ÷ 4 = 3. Divide the letters (same letter: subtract the powers): xy ÷ y = x. Answer: 3x."},{"id":"m016","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 20a^2 ÷ 5a","a":"4a","alt":[],"ex":"Divide the numbers: 20 ÷ 5 = 4. Divide the letters (same letter: subtract the powers): a^2 ÷ a = a. Answer: 4a."},{"id":"m017","topic":0,"unit":3,"day":1,"form":"expr","q":"Simplify 18p^2q ÷ 6pq","a":"3p","alt":[],"ex":"Divide the numbers: 18 ÷ 6 = 3. Divide the letters (same letter: subtract the powers): p^2q ÷ pq = p. Answer: 3p."},{"id":"m018","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand 3(x + 4)","a":"3x + 12","alt":["3x+12"],"ex":"Multiply every term inside the bracket by the term outside: 3 × x = 3x, 3 × 4 = 12. Answer: 3x + 12."},{"id":"m019","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand 5(2y - 3)","a":"10y - 15","alt":["10y-15"],"ex":"Multiply every term inside the bracket by the term outside: 5 × 2y = 10y, 5 × (-3) = -15. Answer: 10y - 15."},{"id":"m020","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand -2(3a + 5)","a":"-6a - 10","alt":["-6a-10"],"ex":"Multiply every term inside the bracket by the term outside: -2 × 3a = -6a, -2 × 5 = -10. Answer: -6a - 10."},{"id":"m021","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand -4(x - 6)","a":"-4x + 24","alt":["-4x+24"],"ex":"Multiply every term inside the bracket by the term outside: -4 × x = -4x, -4 × (-6) = 24. Answer: -4x + 24."},{"id":"m022","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand x(x + 7)","a":"x^2 + 7x","alt":["x^2+7x","x² + 7x"],"ex":"Multiply every term inside the bracket by the term outside: x × x = x^2, x × 7 = 7x. Answer: x^2 + 7x."},{"id":"m023","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand 2a(3a - 4b)","a":"6a^2 - 8ab","alt":["6a^2-8ab","6a² - 8ab"],"ex":"Multiply every term inside the bracket by the term outside: 2a × 3a = 6a^2, 2a × (-4b) = -8ab. Answer: 6a^2 - 8ab."},{"id":"m024","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand 3p(2p + q - 5)","a":"6p^2 + 3pq - 15p","alt":["6p^2+3pq-15p","6p² + 3pq - 15p"],"ex":"Multiply every term inside the bracket by the term outside: 3p × 2p = 6p^2, 3p × q = 3pq, 3p × (-5) = -15p. Answer: 6p^2 + 3pq - 15p."},{"id":"m025","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand -y(4 - 3y)","a":"3y^2 - 4y","alt":["3y^2-4y","3y² - 4y"],"ex":"Multiply every term inside the bracket by the term outside: -y × 4 = -4y, -y × (-3y) = 3y^2. Answer: 3y^2 - 4y."},{"id":"m026","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand and simplify 3(x + 2) + 2(x - 5)","a":"5x - 4","alt":["5x-4"],"ex":"Expand each bracket: 3x + 6 + 2x - 10. Collect like terms: 5x - 4."},{"id":"m027","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand and simplify 4(2y + 1) - 3(y - 2)","a":"5y + 10","alt":["5y+10"],"ex":"Expand each bracket: 8y + 4 - 3y + 6. Collect like terms: 5y + 10."},{"id":"m028","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand and simplify 5(a + 3) - 2(a + 6)","a":"3a + 3","alt":["3a+3"],"ex":"Expand each bracket: 5a + 15 - 2a - 12. Collect like terms: 3a + 3."},{"id":"m029","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand and simplify 2(3x - 1) - (x - 4)","a":"5x + 2","alt":["5x+2"],"ex":"Expand each bracket: 6x - 2 - x + 4. Collect like terms: 5x + 2."},{"id":"m030","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand and simplify x(x + 3) + 2(x - 1)","a":"x^2 + 5x - 2","alt":["x^2+5x-2","x² + 5x - 2"],"ex":"Expand each bracket: x^2 + 3x + 2x - 2. Collect like terms: x^2 + 5x - 2."},{"id":"m031","topic":1,"unit":3,"day":1,"form":"expr","q":"Expand and simplify 3a(a + 2) - a(a - 5)","a":"2a^2 + 11a","alt":["2a^2+11a","2a² + 11a"],"ex":"Expand each bracket: 3a^2 + 6a - a^2 + 5a. Collect like terms: 2a^2 + 11a."},{"id":"m032","topic":2,"unit":3,"day":1,"form":"num","q":"Work out the value of 3a + 2b when a = 4, b = -1 and c = 3.","a":"10","alt":[],"ex":"3 × 4 + 2 × (-1) = 12 - 2 = 10"},{"id":"m033","topic":2,"unit":3,"day":1,"form":"num","q":"Work out the value of a^2 - c when a = 4, b = -1 and c = 3.","a":"13","alt":[],"ex":"4^2 - 3 = 16 - 3 = 13"},{"id":"m034","topic":2,"unit":3,"day":1,"form":"num","q":"Work out the value of 5c - 4b when a = 4, b = -1 and c = 3.","a":"19","alt":[],"ex":"5 × 3 - 4 × (-1) = 15 + 4 = 19"},{"id":"m035","topic":2,"unit":3,"day":1,"form":"num","q":"Work out the value of ab + c when a = 4, b = -1 and c = 3.","a":"-1","alt":[],"ex":"4 × (-1) + 3 = -4 + 3 = -1"},{"id":"m036","topic":2,"unit":3,"day":1,"form":"num","q":"Work out the value of 2a^2 - 3b when a = 4, b = -1 and c = 3.","a":"35","alt":[],"ex":"2 × 16 - 3 × (-1) = 32 + 3 = 35"},{"id":"m037","topic":2,"unit":3,"day":1,"form":"num","q":"Work out the value of (a + c)^2 when a = 4, b = -1 and c = 3.","a":"49","alt":[],"ex":"(4 + 3)^2 = 7^2 = 49"},{"id":"m038","topic":2,"unit":3,"day":1,"form":"num","q":"Work out the value of b^3 + c^2 when a = 4, b = -1 and c = 3.","a":"8","alt":[],"ex":"(-1)^3 + 3^2 = -1 + 9 = 8"},{"id":"m039","topic":0,"unit":3,"day":1,"form":"expr","q":"A rectangle has length 3x + 2 and width x. Write a simplified expression for its perimeter.","a":"8x + 4","alt":["8x+4"],"ex":"Perimeter = 2(3x + 2) + 2 × x = 6x + 4 + 2x = 8x + 4."},{"id":"m040","topic":0,"unit":3,"day":1,"form":"expr","q":"A triangle has sides 2a + 1, 3a - 2 and a + 5. Write a simplified expression for its perimeter.","a":"6a + 4","alt":["6a+4"],"ex":"Add the sides: 2a + 3a + a = 6a and 1 - 2 + 5 = 4, so 6a + 4."},{"id":"m041","topic":0,"unit":3,"day":1,"form":"expr","q":"A rectangle is 4 cm wide and (2x - 3) cm long. Write an expression for its area. Expand the bracket.","a":"8x - 12","alt":["8x-12"],"ex":"Area = 4(2x - 3) = 8x - 12 (cm²)."},{"id":"m042","topic":0,"unit":3,"day":1,"form":"expr","q":"A pen costs p pence. A ruler costs 3 pence more than a pen. Write a simplified expression for the cost of 4 pens and 2 rulers.","a":"6p + 6","alt":["6p+6"],"ex":"Ruler = p + 3. Cost = 4p + 2(p + 3) = 4p + 2p + 6 = 6p + 6 pence."},{"id":"m043","topic":0,"unit":3,"day":1,"form":"expr","q":"Spot the mistake. Sam writes 3(x - 4) = 3x - 4. What is the correct expansion?","a":"3x - 12","alt":["3x-12"],"ex":"Sam only multiplied the first term. The 3 multiplies both terms: 3 × x = 3x and 3 × (-4) = -12, so 3x - 12."},{"id":"m044","topic":0,"unit":3,"day":1,"form":"expr","q":"Spot the mistake. Ali writes -2(y - 5) = -2y - 10. What is the correct expansion?","a":"-2y + 10","alt":["-2y+10"],"ex":"-2 × (-5) = +10 (negative × negative = positive). Correct answer: -2y + 10."},{"id":"m045","topic":0,"unit":3,"day":1,"form":"expr","q":"Spot the mistake. Priya says 4a × 3a = 12a. What is the correct answer?","a":"12a^2","alt":["12a²"],"ex":"a × a = a^2, so 4a × 3a = 12a^2."},{"id":"m046","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise 6x + 9","a":"3(2x + 3)","alt":["3(2x+3)","3(3 + 2x)"],"ex":"HCF of the terms is 3. Divide each term by it: 6x ÷ 3 = 2x, 9 ÷ 3 = 3. Answer: 3(2x + 3). Check: expanding gives 6x + 9."},{"id":"m047","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise 10y - 15","a":"5(2y - 3)","alt":["5(2y-3)"],"ex":"HCF of the terms is 5. Divide each term by it: 10y ÷ 5 = 2y, -15 ÷ 5 = -3. Answer: 5(2y - 3). Check: expanding gives 10y - 15."},{"id":"m048","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise 4a + 12","a":"4(a + 3)","alt":["4(3 + a)","4(a+3)"],"ex":"HCF of the terms is 4. Divide each term by it: 4a ÷ 4 = a, 12 ÷ 4 = 3. Answer: 4(a + 3). Check: expanding gives 4a + 12."},{"id":"m049","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise 14p - 21","a":"7(2p - 3)","alt":["7(2p-3)"],"ex":"HCF of the terms is 7. Divide each term by it: 14p ÷ 7 = 2p, -21 ÷ 7 = -3. Answer: 7(2p - 3). Check: expanding gives 14p - 21."},{"id":"m050","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise 8x + 12y","a":"4(2x + 3y)","alt":["4(2x+3y)","4(3y + 2x)"],"ex":"HCF of the terms is 4. Divide each term by it: 8x ÷ 4 = 2x, 12y ÷ 4 = 3y. Answer: 4(2x + 3y). Check: expanding gives 8x + 12y."},{"id":"m051","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise 5t - 20","a":"5(t - 4)","alt":["5(t-4)"],"ex":"HCF of the terms is 5. Divide each term by it: 5t ÷ 5 = t, -20 ÷ 5 = -4. Answer: 5(t - 4). Check: expanding gives 5t - 20."},{"id":"m052","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise 9m - 6n + 3","a":"3(3m - 2n + 1)","alt":["3(3m-2n+1)"],"ex":"HCF of the terms is 3. Divide each term by it: 9m ÷ 3 = 3m, -6n ÷ 3 = -2n, 3 ÷ 3 = 1. Answer: 3(3m - 2n + 1). Check: expanding gives 9m - 6n + 3."},{"id":"m053","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise 12a + 18b - 6","a":"6(2a + 3b - 1)","alt":["6(2a+3b-1)"],"ex":"HCF of the terms is 6. Divide each term by it: 12a ÷ 6 = 2a, 18b ÷ 6 = 3b, -6 ÷ 6 = -1. Answer: 6(2a + 3b - 1). Check: expanding gives 12a + 18b - 6."},{"id":"m054","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise fully x^2 + 5x","a":"x(x + 5)","alt":["x(5 + x)","x(x+5)"],"ex":"HCF of the terms is x. Divide each term by it: x^2 ÷ x = x, 5x ÷ x = 5. Answer: x(x + 5). Check: expanding gives x^2 + 5x."},{"id":"m055","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise fully 3y^2 - 7y","a":"y(3y - 7)","alt":["y(3y-7)"],"ex":"HCF of the terms is y. Divide each term by it: 3y^2 ÷ y = 3y, -7y ÷ y = -7. Answer: y(3y - 7). Check: expanding gives 3y^2 - 7y."},{"id":"m056","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise fully 6a^2 + 9a","a":"3a(2a + 3)","alt":["3a(2a+3)","3a(3 + 2a)"],"ex":"HCF of the terms is 3a. Divide each term by it: 6a^2 ÷ 3a = 2a, 9a ÷ 3a = 3. Answer: 3a(2a + 3). Check: expanding gives 6a^2 + 9a."},{"id":"m057","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise fully 10x^2 - 15x","a":"5x(2x - 3)","alt":["5x(2x-3)"],"ex":"HCF of the terms is 5x. Divide each term by it: 10x^2 ÷ 5x = 2x, -15x ÷ 5x = -3. Answer: 5x(2x - 3). Check: expanding gives 10x^2 - 15x."},{"id":"m058","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise fully 4pq + 6p","a":"2p(2q + 3)","alt":["2p(2q+3)","2p(3 + 2q)"],"ex":"HCF of the terms is 2p. Divide each term by it: 4pq ÷ 2p = 2q, 6p ÷ 2p = 3. Answer: 2p(2q + 3). Check: expanding gives 4pq + 6p."},{"id":"m059","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise fully 12x^2y - 18xy","a":"6xy(2x - 3)","alt":["6xy(2x-3)"],"ex":"HCF of the terms is 6xy. Divide each term by it: 12x^2y ÷ 6xy = 2x, -18xy ÷ 6xy = -3. Answer: 6xy(2x - 3). Check: expanding gives 12x^2y - 18xy."},{"id":"m060","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise fully 8a^2b + 12ab^2","a":"4ab(2a + 3b)","alt":["4ab(2a+3b)","4ab(3b + 2a)"],"ex":"HCF of the terms is 4ab. Divide each term by it: 8a^2b ÷ 4ab = 2a, 12ab^2 ÷ 4ab = 3b. Answer: 4ab(2a + 3b). Check: expanding gives 8a^2b + 12ab^2."},{"id":"m061","topic":3,"unit":3,"day":2,"form":"factor","q":"Factorise fully 5x^3 - 10x^2","a":"5x^2(x - 2)","alt":["5x^2(x-2)","5x²(x - 2)"],"ex":"HCF of the terms is 5x^2. Divide each term by it: 5x^3 ÷ 5x^2 = x, -10x^2 ÷ 5x^2 = -2. Answer: 5x^2(x - 2). Check: expanding gives 5x^3 - 10x^2."},{"id":"m062","topic":4,"unit":3,"day":2,"form":"mcq","q":"Is 4(2x + 6) fully factorised?","a":"No","alt":[],"ex":"The terms inside the bracket still have a common factor. Expanded it is 8x + 24, whose HCF is 8: 8(x + 3).","choices":["Yes","No"]},{"id":"m063","topic":4,"unit":3,"day":2,"form":"factor","q":"Factorise fully 8x + 24","a":"8(x + 3)","alt":["8(x+3)"],"ex":"HCF is 8, so 8(x + 3)."},{"id":"m064","topic":4,"unit":3,"day":2,"form":"mcq","q":"Is 3(2x + 5) fully factorised?","a":"Yes","alt":[],"ex":"The terms inside the bracket have no common factor, so 3(2x + 5) is fully factorised.","choices":["Yes","No"]},{"id":"m065","topic":4,"unit":3,"day":2,"form":"mcq","q":"Is x(4x + 8) fully factorised?","a":"No","alt":[],"ex":"The terms inside the bracket still have a common factor. Expanded it is 4x^2 + 8x, whose HCF is 4x: 4x(x + 2).","choices":["Yes","No"]},{"id":"m066","topic":4,"unit":3,"day":2,"form":"factor","q":"Factorise fully 4x^2 + 8x","a":"4x(x + 2)","alt":["4x(x+2)"],"ex":"HCF is 4x, so 4x(x + 2)."},{"id":"m067","topic":4,"unit":3,"day":2,"form":"mcq","q":"Is 2x(3x - 7) fully factorised?","a":"Yes","alt":[],"ex":"The terms inside the bracket have no common factor, so 2x(3x - 7) is fully factorised.","choices":["Yes","No"]},{"id":"m068","topic":4,"unit":3,"day":2,"form":"mcq","q":"Is 5(10y - 5) fully factorised?","a":"No","alt":[],"ex":"The terms inside the bracket still have a common factor. Expanded it is 50y - 25, whose HCF is 25: 25(2y - 1).","choices":["Yes","No"]},{"id":"m069","topic":4,"unit":3,"day":2,"form":"factor","q":"Factorise fully 50y - 25","a":"25(2y - 1)","alt":["25(2y-1)"],"ex":"HCF is 25, so 25(2y - 1)."},{"id":"m070","topic":4,"unit":3,"day":2,"form":"mcq","q":"Is a(a^2 + 3a) fully factorised?","a":"No","alt":[],"ex":"The terms inside the bracket still have a common factor. Expanded it is a^3 + 3a^2, whose HCF is a^2: a^2(a + 3).","choices":["Yes","No"]},{"id":"m071","topic":4,"unit":3,"day":2,"form":"factor","q":"Factorise fully a^3 + 3a^2","a":"a^2(a + 3)","alt":["a^2(a+3)","a²(a + 3)"],"ex":"HCF is a^2, so a^2(a + 3)."},{"id":"m072","topic":4,"unit":3,"day":2,"form":"mcq","q":"Is 6(2p + 3q) fully factorised?","a":"Yes","alt":[],"ex":"The terms inside the bracket have no common factor, so 6(2p + 3q) is fully factorised.","choices":["Yes","No"]},{"id":"m073","topic":5,"unit":3,"day":2,"form":"num","q":"Solve 3x + 7 = 22","a":"5","alt":["x = 5","x=5"],"ex":"3x = 15, so x = 5"},{"id":"m074","topic":5,"unit":3,"day":2,"form":"num","q":"Solve 5x - 4 = 31","a":"7","alt":["x = 7","x=7"],"ex":"5x = 35, so x = 7"},{"id":"m075","topic":5,"unit":3,"day":2,"form":"num","q":"Solve 2(x + 3) = 18","a":"6","alt":["x = 6","x=6"],"ex":"2x + 6 = 18, 2x = 12, x = 6"},{"id":"m076","topic":5,"unit":3,"day":2,"form":"num","q":"Solve 4x + 3 = 2x + 11","a":"4","alt":["x = 4","x=4"],"ex":"2x + 3 = 11, 2x = 8, x = 4"},{"id":"m077","topic":5,"unit":3,"day":2,"form":"num","q":"Solve 7 - 2x = 1","a":"3","alt":["x = 3","x=3"],"ex":"7 = 1 + 2x, 6 = 2x, x = 3"},{"id":"m078","topic":5,"unit":3,"day":2,"form":"num","q":"Solve 5(x - 2) = 3x + 4","a":"7","alt":["x = 7","x=7"],"ex":"5x - 10 = 3x + 4, 2x = 14, x = 7"},{"id":"m079","topic":5,"unit":3,"day":2,"form":"num","q":"Solve (x + 4)/3 = 5","a":"11","alt":["x = 11","x=11"],"ex":"x + 4 = 15, x = 11"},{"id":"m080","topic":5,"unit":3,"day":2,"form":"num","q":"Solve 3(2x - 1) = 2(x + 5) + 3","a":"4","alt":["x = 4","x=4"],"ex":"6x - 3 = 2x + 13, 4x = 16, x = 4"},{"id":"m081","topic":6,"unit":3,"day":2,"form":"num","q":"v = u + at. Find a when v = 26, u = 8 and t = 3.","a":"6","alt":["a = 6"],"ex":"26 = 8 + 3a, 18 = 3a, a = 6."},{"id":"m082","topic":6,"unit":3,"day":2,"form":"num","q":"P = 2(l + w). Find w when P = 30 and l = 9.","a":"6","alt":["w = 6"],"ex":"30 = 2(9 + w), 15 = 9 + w, w = 6."},{"id":"m083","topic":6,"unit":3,"day":2,"form":"num","q":"A = ½bh. Find h when A = 24 and b = 8.","a":"6","alt":["h = 6"],"ex":"24 = ½ × 8 × h = 4h, h = 6."},{"id":"m084","topic":6,"unit":3,"day":2,"form":"num","q":"y = mx + c. Find x when y = 17, m = 3 and c = 2.","a":"5","alt":["x = 5"],"ex":"17 = 3x + 2, 15 = 3x, x = 5."},{"id":"m085","topic":6,"unit":3,"day":2,"form":"num","q":"F = ma. Find a when F = 42 and m = 6.","a":"7","alt":["a = 7"],"ex":"42 = 6a, a = 7."},{"id":"m086","topic":6,"unit":3,"day":2,"form":"num","q":"The time T minutes to cook a chicken of mass w kg is T = 20w + 30. Find w when T = 110.","a":"4","alt":["w = 4"],"ex":"110 = 20w + 30, 80 = 20w, w = 4 kg."},{"id":"m087","topic":6,"unit":3,"day":2,"form":"num","q":"s = (u + v)t/2. Find v when s = 60, u = 4 and t = 8.","a":"11","alt":["v = 11"],"ex":"60 = (4 + v) × 8 ÷ 2 = 4(4 + v), 15 = 4 + v, v = 11."},{"id":"m088","topic":6,"unit":3,"day":2,"form":"num","q":"E = 3m^2. Find the positive value of m when E = 75.","a":"5","alt":["m = 5"],"ex":"75 = 3m^2, m^2 = 25, m = 5 (positive)."},{"id":"m089","topic":6,"unit":3,"day":2,"form":"num","q":"A plumber charges C = 25 + 12h pounds for h hours. A job costs £97. How many hours?","a":"6","alt":["h = 6"],"ex":"97 = 25 + 12h, 72 = 12h, h = 6 hours."},{"id":"m090","topic":5,"unit":3,"day":2,"form":"factor","q":"Spot the mistake. Mia factorises 12x + 8 as 2(6x + 4). Write the correct full factorisation.","a":"4(3x + 2)","alt":["4(2 + 3x)","4(3x+2)"],"ex":"6x + 4 still has a common factor 2. The HCF of 12x and 8 is 4: 12x + 8 = 4(3x + 2)."},{"id":"m091","topic":5,"unit":3,"day":2,"form":"num","q":"Spot the mistake. Leo solves 3x + 5 = 20 like this: 3x = 25, so x = 25/3. Find the correct value of x.","a":"5","alt":[],"ex":"Leo added 5 instead of subtracting it. 3x = 20 - 5 = 15, so x = 5."},{"id":"m092","topic":5,"unit":3,"day":2,"form":"num","q":"I think of a number, multiply it by 4 and subtract 7. The answer is 33. What was my number?","a":"10","alt":[],"ex":"Let the number be n: 4n - 7 = 33, 4n = 40, n = 10."},{"id":"m093","topic":5,"unit":3,"day":2,"form":"num","q":"A taxi costs C = 3 + 2m pounds for m miles. A journey costs £19. How many miles was it?","a":"8","alt":[],"ex":"19 = 3 + 2m, 16 = 2m, m = 8 miles."},{"id":"m094","topic":7,"unit":3,"day":3,"form":"index","q":"Simplify 5^3 × 5^4","a":"5^7","alt":[],"ex":"Same base, so add the powers: 3 + 4 = 7. Answer: 5^7."},{"id":"m095","topic":7,"unit":3,"day":3,"form":"index","q":"Simplify 7^9 ÷ 7^4","a":"7^5","alt":[],"ex":"Same base, so subtract the powers: 9 - 4 = 5. Answer: 7^5."},{"id":"m096","topic":7,"unit":3,"day":3,"form":"index","q":"Simplify (3^2)^5","a":"3^10","alt":[],"ex":"Same base, so multiply the powers: 2 × 5 = 10. Answer: 3^10."},{"id":"m097","topic":7,"unit":3,"day":3,"form":"index","q":"Simplify 2^3 × 2^5 ÷ 2^4","a":"2^4","alt":[],"ex":"Same base, so 3 + 5 - 4 = 4. Answer: 2^4."},{"id":"m098","topic":7,"unit":3,"day":3,"form":"index","q":"Simplify (6^4 × 6^5) ÷ 6^7","a":"6^2","alt":["6²"],"ex":"Same base, so 4 + 5 = 9, then 9 - 7 = 2. Answer: 6^2."},{"id":"m099","topic":7,"unit":3,"day":3,"form":"index","q":"Simplify 10^2 × 10^3 × 10","a":"10^6","alt":[],"ex":"Same base, so 10 = 10^1, so 2 + 3 + 1 = 6. Answer: 10^6."},{"id":"m100","topic":7,"unit":3,"day":3,"form":"index","q":"Simplify (9^3)^2 ÷ 9^4","a":"9^2","alt":["9²"],"ex":"Same base, so 3 × 2 = 6, then 6 - 4 = 2. Answer: 9^2."},{"id":"m101","topic":7,"unit":3,"day":3,"form":"index","q":"Simplify 4^5 ÷ 4^5","a":"1","alt":["4^0"],"ex":"Same base, so 5 - 5 = 0 and 4^0 = 1. Answer: 1."},{"id":"m102","topic":7,"unit":3,"day":3,"form":"num","q":"Find n if 3^n × 3^4 = 3^11","a":"7","alt":["n = 7"],"ex":"n + 4 = 11, so n = 7."},{"id":"m103","topic":7,"unit":3,"day":3,"form":"num","q":"Find n if 8^12 ÷ 8^n = 8^5","a":"7","alt":["n = 7"],"ex":"12 - n = 5, so n = 7."},{"id":"m104","topic":7,"unit":3,"day":3,"form":"num","q":"Work out 2^3 × 2^2 as an ordinary number.","a":"32","alt":[],"ex":"2^3 × 2^2 = 2^5 = 32."},{"id":"m105","topic":8,"unit":3,"day":3,"form":"expr","q":"Simplify x^3 × x^5","a":"x^8","alt":[],"ex":"Multiply the numbers: 1 × 1 = 1. Multiply the letters (same letter: add the powers): x^3 × x^5 = x^8. Answer: x^8."},{"id":"m106","topic":8,"unit":3,"day":3,"form":"expr","q":"Simplify 3a^2 × 4a^5","a":"12a^7","alt":[],"ex":"Multiply the numbers: 3 × 4 = 12. Multiply the letters (same letter: add the powers): a^2 × a^5 = a^7. Answer: 12a^7."},{"id":"m107","topic":8,"unit":3,"day":3,"form":"expr","q":"Simplify 2x^3y × 5xy^4","a":"10x^4y^5","alt":[],"ex":"Multiply the numbers: 2 × 5 = 10. Multiply the letters (same letter: add the powers): x^3y × xy^4 = x^4y^5. Answer: 10x^4y^5."},{"id":"m108","topic":8,"unit":3,"day":3,"form":"expr","q":"Simplify 20x^8 ÷ 5x^3","a":"4x^5","alt":[],"ex":"Divide the numbers: 20 ÷ 5 = 4. Divide the letters (same letter: subtract the powers): x^8 ÷ x^3 = x^5. Answer: 4x^5."},{"id":"m109","topic":8,"unit":3,"day":3,"form":"expr","q":"Simplify 18a^5b^3 ÷ 6a^2b","a":"3a^3b^2","alt":["3a³b²"],"ex":"Divide the numbers: 18 ÷ 6 = 3. Divide the letters (same letter: subtract the powers): a^5b^3 ÷ a^2b = a^3b^2. Answer: 3a^3b^2."},{"id":"m110","topic":8,"unit":3,"day":3,"form":"expr","q":"Simplify x^7 ÷ x^7","a":"1","alt":[],"ex":"Divide the numbers: 1 ÷ 1 = 1. Divide the letters (same letter: subtract the powers): x^7 ÷ x^7 = 1. Answer: 1."},{"id":"m111","topic":8,"unit":3,"day":3,"form":"expr","q":"Simplify (y^4)^3","a":"y^12","alt":[],"ex":"Multiply the powers: 4 × 3 = 12. Answer: y^12."},{"id":"m112","topic":8,"unit":3,"day":3,"form":"expr","q":"Simplify (2x^3)^4","a":"16x^12","alt":[],"ex":"2^4 = 16 and x^(3×4) = x^12. Answer: 16x^12."},{"id":"m113","topic":8,"unit":3,"day":3,"form":"expr","q":"Simplify (3a^2b)^3","a":"27a^6b^3","alt":["27a^6b³"],"ex":"3^3 = 27, a^(2×3) = a^6, b^3. Answer: 27a^6b^3."},{"id":"m114","topic":8,"unit":3,"day":3,"form":"expr","q":"Simplify (4x^3)^2 ÷ 8x^2","a":"2x^4","alt":[],"ex":"(4x^3)^2 = 16x^6; 16x^6 ÷ 8x^2 = 2x^4."},{"id":"m115","topic":8,"unit":3,"day":3,"form":"expr","q":"Simplify (6x^5y^3 × 2xy) ÷ 4x^2y^2","a":"3x^4y^2","alt":["3x^4y²"],"ex":"Top: 12x^6y^4. Divide by 4x^2y^2: 3x^4y^2."},{"id":"m116","topic":9,"unit":3,"day":3,"form":"expr","q":"Expand x^2(x^3 + 4)","a":"x^5 + 4x^2","alt":["x^5 + 4x²","x^5+4x^2"],"ex":"Multiply every term inside the bracket by the term outside: x^2 × x^3 = x^5, x^2 × 4 = 4x^2. Answer: x^5 + 4x^2."},{"id":"m117","topic":9,"unit":3,"day":3,"form":"expr","q":"Expand 3a^2(2a^3 - 5a)","a":"6a^5 - 15a^3","alt":["6a^5 - 15a³","6a^5-15a^3"],"ex":"Multiply every term inside the bracket by the term outside: 3a^2 × 2a^3 = 6a^5, 3a^2 × (-5a) = -15a^3. Answer: 6a^5 - 15a^3."},{"id":"m118","topic":9,"unit":3,"day":3,"form":"expr","q":"Expand 2x^3(4x^2 + 3x - 1)","a":"8x^5 + 6x^4 - 2x^3","alt":["8x^5 + 6x^4 - 2x³","8x^5+6x^4-2x^3"],"ex":"Multiply every term inside the bracket by the term outside: 2x^3 × 4x^2 = 8x^5, 2x^3 × 3x = 6x^4, 2x^3 × (-1) = -2x^3. Answer: 8x^5 + 6x^4 - 2x^3."},{"id":"m119","topic":9,"unit":3,"day":3,"form":"expr","q":"Expand and simplify x(x + 3) + x(2x - 5)","a":"3x^2 - 2x","alt":["3x^2-2x","3x² - 2x"],"ex":"Expand each bracket: x^2 + 3x + 2x^2 - 5x. Collect like terms: 3x^2 - 2x."},{"id":"m120","topic":9,"unit":3,"day":3,"form":"expr","q":"Expand and simplify a^2(a + 3) - a(a^2 - 2a)","a":"5a^2","alt":["5a²"],"ex":"Expand each bracket: a^3 + 3a^2 - a^3 + 2a^2. Collect like terms: 5a^2."},{"id":"m121","topic":9,"unit":3,"day":3,"form":"expr","q":"Simplify (2x^2)^3 + x^2 × 3x^4","a":"11x^6","alt":[],"ex":"(2x^2)^3 = 8x^6 and x^2 × 3x^4 = 3x^6. Like terms: 8x^6 + 3x^6 = 11x^6."},{"id":"m122","topic":9,"unit":3,"day":3,"form":"factor","q":"Factorise fully x^5 + x^3","a":"x^3(x^2 + 1)","alt":["x^3(1 + x^2)","x^3(x^2+1)","x³(x² + 1)"],"ex":"HCF of the terms is x^3. Divide each term by it: x^5 ÷ x^3 = x^2, x^3 ÷ x^3 = 1. Answer: x^3(x^2 + 1). Check: expanding gives x^5 + x^3."},{"id":"m123","topic":9,"unit":3,"day":3,"form":"factor","q":"Factorise fully 6a^4 - 9a^2","a":"3a^2(2a^2 - 3)","alt":["3a^2(2a^2-3)","3a²(2a² - 3)"],"ex":"HCF of the terms is 3a^2. Divide each term by it: 6a^4 ÷ 3a^2 = 2a^2, -9a^2 ÷ 3a^2 = -3. Answer: 3a^2(2a^2 - 3). Check: expanding gives 6a^4 - 9a^2."},{"id":"m124","topic":9,"unit":3,"day":3,"form":"factor","q":"Factorise fully 4x^3y + 10x^2y^2","a":"2x^2y(2x + 5y)","alt":["2x^2y(2x+5y)","2x^2y(5y + 2x)","2x²y(2x + 5y)"],"ex":"HCF of the terms is 2x^2y. Divide each term by it: 4x^3y ÷ 2x^2y = 2x, 10x^2y^2 ÷ 2x^2y = 5y. Answer: 2x^2y(2x + 5y). Check: expanding gives 4x^3y + 10x^2y^2."},{"id":"m125","topic":10,"unit":3,"day":3,"form":"num","q":"The angles of a triangle are x, 2x and x + 20 degrees. Find x.","a":"40","alt":["40 °","x = 40"],"ex":"4x + 20 = 180, 4x = 160, x = 40.","units":"°","fig":"g_tri1.svg"},{"id":"m126","topic":10,"unit":3,"day":3,"form":"num","q":"Two angles on a straight line are 3x and x + 40 degrees. Find x.","a":"35","alt":["35 °","x = 35"],"ex":"4x + 40 = 180, 4x = 140, x = 35.","units":"°","fig":"g_line1.svg"},{"id":"m127","topic":10,"unit":3,"day":3,"form":"num","q":"Three angles on a straight line are 2x, 50° and 3x. Find x.","a":"26","alt":["26 °","x = 26"],"ex":"5x + 50 = 180, 5x = 130, x = 26.","units":"°","fig":"g_line2.svg"},{"id":"m128","topic":10,"unit":3,"day":3,"form":"num","q":"Four angles around a point are x, 2x, 3x and 90°. Find x.","a":"45","alt":["45 °","x = 45"],"ex":"6x + 90 = 360, 6x = 270, x = 45.","units":"°","fig":"g_point1.svg"},{"id":"m129","topic":10,"unit":3,"day":3,"form":"num","q":"The angles of a quadrilateral are x, x + 30, 2x and 2x - 30 degrees. Find x.","a":"60","alt":["60 °","x = 60"],"ex":"6x = 360, x = 60.","units":"°","fig":"g_quad1.svg"},{"id":"m130","topic":10,"unit":3,"day":3,"form":"num","q":"An isosceles triangle has equal base angles 3x + 10 and 5x - 20 degrees. Find x.","a":"15","alt":["15 °","x = 15"],"ex":"Base angles are equal: 3x + 10 = 5x - 20, 30 = 2x, x = 15 (each base angle is 55°).","units":"°","fig":"g_isos.svg"},{"id":"m131","topic":10,"unit":3,"day":3,"form":"num","q":"A rectangle has length 2x + 3 and width x - 1. Its perimeter is 40 cm. Find x.","a":"6","alt":["x = 6"],"ex":"2(2x + 3) + 2(x - 1) = 40, 6x + 4 = 40, 6x = 36, x = 6.","fig":"rect1.svg"},{"id":"m132","topic":10,"unit":3,"day":3,"form":"num","q":"An equilateral triangle has sides 2x + 1 and 3x - 4 (cm). Find x.","a":"5","alt":["x = 5"],"ex":"Sides are equal: 2x + 1 = 3x - 4, so x = 5.","fig":"equi.svg"},{"id":"m133","topic":10,"unit":3,"day":3,"form":"num","q":"An equilateral triangle has sides (2x + 1) cm and (3x - 4) cm. Find its perimeter.","a":"33","alt":["33 cm"],"ex":"Each side = 2 × 5 + 1 = 11 cm; perimeter = 3 × 11 = 33 cm.","units":"cm","fig":"equi.svg"},{"id":"m134","topic":10,"unit":3,"day":3,"form":"num","q":"A rectangle is 5 cm wide and (x + 3) cm long. Its area is 45 cm². Find x.","a":"6","alt":["x = 6"],"ex":"5(x + 3) = 45, x + 3 = 9, x = 6.","fig":"rect2.svg"},{"id":"m135","topic":10,"unit":3,"day":3,"form":"num","q":"A triangle has base 8 cm and height (2x - 1) cm. Its area is 36 cm². Find x.","a":"5","alt":["x = 5"],"ex":"½ × 8 × (2x - 1) = 36, 4(2x - 1) = 36, 2x - 1 = 9, x = 5.","fig":"tri_h.svg"},{"id":"m136","topic":10,"unit":3,"day":3,"form":"num","q":"A square has side (3x - 2) cm and perimeter 52 cm. Find x.","a":"5","alt":["x = 5"],"ex":"4(3x - 2) = 52, 3x - 2 = 13, x = 5."},{"id":"m137","topic":11,"unit":3,"day":3,"form":"expr","q":"Spot the mistake. Zara writes x^3 × x^4 = x^12. Correct it.","a":"x^7","alt":[],"ex":"When multiplying, ADD the powers: 3 + 4 = 7, so x^7."},{"id":"m138","topic":11,"unit":3,"day":3,"form":"expr","q":"Spot the mistake. Tom writes (2a^3)^2 = 2a^6. Correct it.","a":"4a^6","alt":[],"ex":"The 2 must be squared too: 2^2 = 4, so 4a^6."},{"id":"m139","topic":11,"unit":3,"day":3,"form":"num","q":"Spot the mistake. Kim writes 2^3 × 3^2 = 6^5. Work out the correct value.","a":"72","alt":[],"ex":"Different bases, so the laws do not apply: 8 × 9 = 72."},{"id":"m140","topic":11,"unit":3,"day":3,"form":"num","q":"Find n if (x^n)^3 ÷ x^2 = x^13","a":"5","alt":["n = 5"],"ex":"3n - 2 = 13, 3n = 15, n = 5."},{"id":"m141","topic":11,"unit":3,"day":3,"form":"num","q":"Find k if 5^k = 125","a":"3","alt":["k = 3"],"ex":"5 × 5 × 5 = 125, so k = 3."},{"id":"m142","topic":11,"unit":3,"day":3,"form":"num","q":"Find n if 2^3 × 2^n = 64","a":"3","alt":["n = 3"],"ex":"64 = 2^6, so 3 + n = 6, n = 3."},{"id":"m143","topic":12,"unit":4,"day":4,"form":"num","q":"Find the area of this parallelogram.","a":"40","alt":["40 cm²"],"ex":"A = b × h = 8 × 5 = 40 cm². (The slanted side is not used.)","units":"cm²","fig":"para0.svg"},{"id":"m144","topic":12,"unit":4,"day":4,"form":"num","q":"Find the area of this parallelogram.","a":"84","alt":["84 cm²"],"ex":"A = b × h = 12 × 7 = 84 cm².","units":"cm²","fig":"para1.svg"},{"id":"m145","topic":12,"unit":4,"day":4,"form":"num","q":"Find the area of this parallelogram.","a":"40.5","alt":["40.5 cm²"],"ex":"A = b × h = 9 × 4.5 = 40.5 cm².","units":"cm²","fig":"para2.svg"},{"id":"m146","topic":12,"unit":4,"day":4,"form":"num","q":"Find the area of this parallelogram.","a":"21","alt":["21 m²"],"ex":"A = b × h = 6 × 3.5 = 21 m². (The slanted side is not used.)","units":"m²","fig":"para3.svg"},{"id":"m147","topic":12,"unit":4,"day":4,"form":"num","q":"Find the area of this parallelogram.","a":"60","alt":["60 cm²"],"ex":"A = b × h = 10 × 6 = 60 cm². (The slanted side is not used.)","units":"cm²","fig":"para4.svg"},{"id":"m148","topic":12,"unit":4,"day":4,"form":"num","q":"A parallelogram has area 48 cm² and base 8 cm. Find its perpendicular height.","a":"6","alt":["6 cm"],"ex":"8 × h = 48, so h = 6 cm.","units":"cm"},{"id":"m149","topic":12,"unit":4,"day":4,"form":"num","q":"A parallelogram has area 63 cm² and height 7 cm. Find its base.","a":"9","alt":["9 cm"],"ex":"b × 7 = 63, so b = 9 cm.","units":"cm"},{"id":"m150","topic":12,"unit":4,"day":4,"form":"num","q":"Find the area of this triangle.","a":"12","alt":["12 cm²"],"ex":"A = ½ × 6 × 4 = 12 cm².","units":"cm²","fig":"tri0.svg"},{"id":"m151","topic":12,"unit":4,"day":4,"form":"num","q":"Find the area of this triangle.","a":"35","alt":["35 cm²"],"ex":"A = ½ × 10 × 7 = 35 cm².","units":"cm²","fig":"tri1.svg"},{"id":"m152","topic":12,"unit":4,"day":4,"form":"num","q":"Find the area of this triangle.","a":"54","alt":["54 cm²"],"ex":"A = ½ × 12 × 9 = 54 cm². (15 cm is the sloping side - not needed.)","units":"cm²","fig":"tri2.svg"},{"id":"m153","topic":12,"unit":4,"day":4,"form":"num","q":"Find the area of this triangle.","a":"17.5","alt":["17.5 cm²"],"ex":"A = ½ × 7 × 5 = 17.5 cm².","units":"cm²","fig":"tri3.svg"},{"id":"m154","topic":12,"unit":4,"day":4,"form":"num","q":"Find the area of this triangle.","a":"63","alt":["63 cm²"],"ex":"A = ½ × 14 × 9 = 63 cm².","units":"cm²","fig":"tri4.svg"},{"id":"m155","topic":12,"unit":4,"day":4,"form":"num","q":"A triangle has area 30 cm² and base 12 cm. Find its height.","a":"5","alt":["5 cm"],"ex":"½ × 12 × h = 30, 6h = 30, h = 5 cm.","units":"cm"},{"id":"m156","topic":12,"unit":4,"day":4,"form":"num","q":"A triangle has area 27 cm² and height 6 cm. Find its base.","a":"9","alt":["9 cm"],"ex":"½ × b × 6 = 27, 3b = 27, b = 9 cm.","units":"cm"},{"id":"m157","topic":13,"unit":4,"day":4,"form":"num","q":"Find the area of this trapezium.","a":"18","alt":["18 cm²"],"ex":"A = ½(4 + 8) × 3 = ½ × 12 × 3 = 18 cm².","units":"cm²","fig":"trap0.svg"},{"id":"m158","topic":13,"unit":4,"day":4,"form":"num","q":"Find the area of this trapezium.","a":"60","alt":["60 cm²"],"ex":"A = ½(7 + 13) × 6 = ½ × 20 × 6 = 60 cm².","units":"cm²","fig":"trap1.svg"},{"id":"m159","topic":13,"unit":4,"day":4,"form":"num","q":"Find the area of this trapezium.","a":"31.5","alt":["31.5 cm²"],"ex":"A = ½(5 + 9) × 4.5 = ½ × 14 × 4.5 = 31.5 cm².","units":"cm²","fig":"trap2.svg"},{"id":"m160","topic":13,"unit":4,"day":4,"form":"num","q":"Find the area of this trapezium.","a":"160","alt":["160 cm²"],"ex":"A = ½(12 + 20) × 10 = ½ × 32 × 10 = 160 cm².","units":"cm²","fig":"trap3.svg"},{"id":"m161","topic":13,"unit":4,"day":4,"form":"num","q":"Find the area of this trapezium.","a":"20","alt":["20 cm²"],"ex":"A = ½(3 + 7) × 4 = ½ × 10 × 4 = 20 cm².","units":"cm²","fig":"trap4.svg"},{"id":"m162","topic":13,"unit":4,"day":4,"form":"num","q":"Find the area of this trapezium.","a":"24","alt":["24 cm²"],"ex":"A = ½(2.5 + 5.5) × 6 = ½ × 8 × 6 = 24 cm².","units":"cm²","fig":"trap5.svg"},{"id":"m163","topic":13,"unit":4,"day":4,"form":"num","q":"Two identical trapezia (parallel sides 5 cm and 9 cm, height 4 cm) fit together to make a parallelogram. What is the base of the parallelogram?","a":"14","alt":["14 cm"],"ex":"The base is 5 + 9 = 14 cm (one short side + one long side).","units":"cm","fig":"twotrap.svg"},{"id":"m164","topic":13,"unit":4,"day":4,"form":"num","q":"Two identical trapezia (parallel sides 5 cm and 9 cm, height 4 cm) fit together to make a parallelogram. Find the area of this parallelogram.","a":"56","alt":["56 cm²"],"ex":"14 × 4 = 56 cm².","units":"cm²","fig":"twotrap.svg"},{"id":"m165","topic":13,"unit":4,"day":4,"form":"num","q":"Two identical trapezia (parallel sides 5 cm and 9 cm, height 4 cm) make a parallelogram of area 56 cm². Find the area of ONE trapezium.","a":"28","alt":["28 cm²"],"ex":"56 ÷ 2 = 28 cm². In general: area = ½(a + b)h.","units":"cm²","fig":"twotrap.svg"},{"id":"m166","topic":13,"unit":4,"day":4,"form":"num","q":"A trapezium has area 60 cm², height 6 cm and one parallel side 7 cm. Find the other parallel side.","a":"13","alt":["13 cm"],"ex":"½(7 + b) × 6 = 60, 3(7 + b) = 60, 7 + b = 20, b = 13 cm.","units":"cm"},{"id":"m167","topic":13,"unit":4,"day":4,"form":"num","q":"A trapezium has parallel sides 4 cm and 11 cm and area 45 cm². Find its height.","a":"6","alt":["6 cm"],"ex":"½ × 15 × h = 45, 7.5h = 45, h = 6 cm.","units":"cm"},{"id":"m168","topic":13,"unit":4,"day":4,"form":"num","q":"The parallel sides of a trapezium are x cm and (x + 4) cm. Its height is 5 cm and its area is 50 cm². Find x.","a":"8","alt":["x = 8"],"ex":"½(2x + 4) × 5 = 50, (x + 2) × 5 = 50, x + 2 = 10, x = 8.","fig":"trapx.svg"},{"id":"m169","topic":13,"unit":4,"day":4,"form":"num","q":"A triangle has base 2x cm, height 8 cm and area 40 cm². Find x.","a":"5","alt":["x = 5"],"ex":"½ × 2x × 8 = 8x = 40, x = 5."},{"id":"m170","topic":13,"unit":4,"day":4,"form":"num","q":"A parallelogram has base (x + 3) cm, height 6 cm and area 54 cm². Find x.","a":"6","alt":["x = 6"],"ex":"6(x + 3) = 54, x + 3 = 9, x = 6."},{"id":"m171","topic":14,"unit":4,"day":4,"form":"num","q":"Find the area of this shape (a rectangle with a triangle on top).","a":"52","alt":["52 cm²"],"ex":"Rectangle 8 × 5 = 40; triangle ½ × 8 × 3 = 12; total 40 + 12 = 52 cm².","units":"cm²","fig":"house.svg"},{"id":"m172","topic":14,"unit":4,"day":4,"form":"num","q":"A triangle (base 4 cm, height 3 cm) is cut out of a 10 cm by 6 cm rectangle. Find the area that is left.","a":"54","alt":["54 cm²"],"ex":"Rectangle 10 × 6 = 60; triangle ½ × 4 × 3 = 6; left: 60 - 6 = 54 cm².","units":"cm²","fig":"cutout.svg"},{"id":"m173","topic":14,"unit":4,"day":4,"form":"num","q":"A logo is a parallelogram (base 6 cm, height 4 cm) with a triangle (base 6 cm, height 3 cm) on top. Find its total area.","a":"33","alt":["33 cm²"],"ex":"Parallelogram 6 × 4 = 24; triangle ½ × 6 × 3 = 9; total 33 cm².","units":"cm²","fig":"logo.svg"},{"id":"m174","topic":14,"unit":4,"day":4,"form":"num","q":"A lawn is a trapezium with parallel sides 12 m and 18 m and width (height) 8 m. Find its area.","a":"120","alt":["120 m²"],"ex":"½(12 + 18) × 8 = 15 × 8 = 120 m².","units":"m²"},{"id":"m175","topic":14,"unit":4,"day":4,"form":"num","q":"Turf for the lawn costs £4 per m². Find the total cost in pounds.","a":"480","alt":[],"ex":"120 × 4 = £480.","units":"£"},{"id":"m176","topic":14,"unit":4,"day":4,"form":"num","q":"A field is a trapezium with parallel sides 40 m and 60 m and height 30 m. One bag of seed covers 100 m². How many bags are needed?","a":"15","alt":[],"ex":"Area = ½ × 100 × 30 = 1500 m²; 1500 ÷ 100 = 15 bags."},{"id":"m177","topic":14,"unit":4,"day":4,"form":"num","q":"A triangle and a parallelogram have the same area. The parallelogram has base 9 cm and height 4 cm. The triangle has base 12 cm. Find the height of the triangle.","a":"6","alt":["6 cm"],"ex":"Parallelogram = 36 cm²; ½ × 12 × h = 36, 6h = 36, h = 6 cm.","units":"cm"},{"id":"m178","topic":12,"unit":4,"day":4,"form":"num","q":"Spot the mistake. Ben says a parallelogram with base 10 cm, slanted side 7 cm and height 6 cm has area 10 × 7 = 70 cm². Find the correct area.","a":"60","alt":["60 cm²"],"ex":"Use the perpendicular height, not the slanted side: 10 × 6 = 60 cm².","units":"cm²"},{"id":"m179","topic":12,"unit":4,"day":4,"form":"num","q":"Spot the mistake. Ella says a triangle with base 8 cm and height 5 cm has area 40 cm². Find the correct area.","a":"20","alt":["20 cm²"],"ex":"She forgot the ½: ½ × 8 × 5 = 20 cm².","units":"cm²"},{"id":"m180","topic":12,"unit":4,"day":4,"form":"num","q":"Spot the mistake. Josh finds the area of a trapezium with parallel sides 4 cm and 6 cm and height 3 cm as 4 + 6 × 3 ÷ 2 = 13. Find the correct area.","a":"15","alt":["15 cm²"],"ex":"Add the parallel sides FIRST (brackets): ½ × (4 + 6) × 3 = 15 cm².","units":"cm²"},{"id":"m181","topic":15,"unit":4,"day":5,"form":"num","q":"Find the volume of this cuboid.","a":"42","alt":["42 cm³"],"ex":"V = 7 × 3 × 2 = 42 cm³.","units":"cm³","fig":"cubv0.svg"},{"id":"m182","topic":15,"unit":4,"day":5,"form":"num","q":"Find the volume of this cuboid.","a":"160","alt":["160 cm³"],"ex":"V = 8 × 5 × 4 = 160 cm³.","units":"cm³","fig":"cubv1.svg"},{"id":"m183","topic":15,"unit":4,"day":5,"form":"num","q":"Find the volume of this cube.","a":"27","alt":["27 cm³"],"ex":"V = 3^3 = 27 cm³.","units":"cm³","fig":"cube3.svg"},{"id":"m184","topic":15,"unit":4,"day":5,"form":"num","q":"Find the volume of a cube with edge 6 cm.","a":"216","alt":["216 cm³"],"ex":"6^3 = 216 cm³.","units":"cm³"},{"id":"m185","topic":15,"unit":4,"day":5,"form":"num","q":"Find the volume of a cuboid 10 cm by 2.5 cm by 4 cm.","a":"100","alt":["100 cm³"],"ex":"10 × 2.5 × 4 = 100 cm³.","units":"cm³"},{"id":"m186","topic":15,"unit":4,"day":5,"form":"num","q":"Find the volume of a cuboid 12 cm by 5 cm by 1.5 cm.","a":"90","alt":["90 cm³"],"ex":"12 × 5 × 1.5 = 90 cm³.","units":"cm³"},{"id":"m187","topic":15,"unit":4,"day":5,"form":"num","q":"A box is 2 m by 1.5 m by 0.8 m. Find its volume.","a":"2.4","alt":["2.4 m³"],"ex":"2 × 1.5 × 0.8 = 2.4 m³.","units":"m³"},{"id":"m188","topic":15,"unit":4,"day":5,"form":"expr","q":"A cuboid has edges a, 2a and 3a. Write an expression for its volume.","a":"6a^3","alt":["6a³"],"ex":"a × 2a × 3a = 6a^3."},{"id":"m189","topic":16,"unit":4,"day":5,"form":"num","q":"Find the surface area of this cuboid.","a":"52","alt":["52 cm²"],"ex":"Faces: 4 × 3 = 12, 4 × 2 = 8, 3 × 2 = 6. SA = 2(12 + 8 + 6) = 52 cm².","units":"cm²","fig":"cubs0.svg"},{"id":"m190","topic":16,"unit":4,"day":5,"form":"num","q":"Find the surface area of this cuboid.","a":"216","alt":["216 cm²"],"ex":"Faces: 10 × 6 = 60, 10 × 3 = 30, 6 × 3 = 18. SA = 2(60 + 30 + 18) = 216 cm².","units":"cm²","fig":"cubs1.svg"},{"id":"m191","topic":16,"unit":4,"day":5,"form":"num","q":"Find the surface area of this cube.","a":"96","alt":["96 cm²"],"ex":"6 × 4^2 = 6 × 16 = 96 cm².","units":"cm²","fig":"cube4.svg"},{"id":"m192","topic":16,"unit":4,"day":5,"form":"num","q":"Find the surface area of a cuboid 5 cm by 5 cm by 2 cm.","a":"90","alt":["90 cm²"],"ex":"2(25 + 10 + 10) = 90 cm².","units":"cm²"},{"id":"m193","topic":16,"unit":4,"day":5,"form":"num","q":"Find the surface area of a cuboid 8 cm by 3 cm by 1 cm.","a":"70","alt":["70 cm²"],"ex":"2(24 + 8 + 3) = 70 cm².","units":"cm²"},{"id":"m194","topic":16,"unit":4,"day":5,"form":"num","q":"Find the surface area of a cuboid 6 cm by 5 cm by 4 cm.","a":"148","alt":["148 cm²"],"ex":"2(30 + 24 + 20) = 148 cm².","units":"cm²"},{"id":"m195","topic":16,"unit":4,"day":5,"form":"num","q":"Find the surface area of a cuboid 12 cm by 10 cm by 0.5 cm.","a":"262","alt":["262 cm²"],"ex":"2(120 + 6 + 5) = 262 cm².","units":"cm²"},{"id":"m196","topic":16,"unit":4,"day":5,"form":"num","q":"Find the surface area of a cube with edge 2.5 cm.","a":"37.5","alt":["37.5 cm²"],"ex":"6 × 2.5^2 = 6 × 6.25 = 37.5 cm².","units":"cm²"},{"id":"m197","topic":15,"unit":4,"day":5,"form":"num","q":"A cuboid has volume 120 cm³, length 6 cm and width 5 cm. Find its height.","a":"4","alt":["4 cm"],"ex":"30h = 120, h = 4 cm.","units":"cm"},{"id":"m198","topic":15,"unit":4,"day":5,"form":"num","q":"A cuboid has volume 200 cm³ and a base 10 cm by 4 cm. Find its height.","a":"5","alt":["5 cm"],"ex":"40h = 200, h = 5 cm.","units":"cm"},{"id":"m199","topic":15,"unit":4,"day":5,"form":"num","q":"A cube has volume 64 cm³. Find the length of one edge.","a":"4","alt":["4 cm"],"ex":"4 × 4 × 4 = 64, so edge = 4 cm.","units":"cm"},{"id":"m200","topic":15,"unit":4,"day":5,"form":"num","q":"A cube has volume 64 cm³. Find its surface area.","a":"96","alt":["96 cm²"],"ex":"Edge 4 cm, SA = 6 × 16 = 96 cm².","units":"cm²"},{"id":"m201","topic":15,"unit":4,"day":5,"form":"num","q":"A cube has surface area 150 cm². Find the length of one edge.","a":"5","alt":["5 cm"],"ex":"One face = 150 ÷ 6 = 25 cm², edge = 5 cm.","units":"cm"},{"id":"m202","topic":15,"unit":4,"day":5,"form":"num","q":"The edge of a cube is doubled from 3 cm to 6 cm. How many times bigger is the volume?","a":"8","alt":[],"ex":"216 ÷ 27 = 8 times."},{"id":"m203","topic":17,"unit":4,"day":5,"form":"num","q":"This solid is made from cuboids. Find its volume.","a":"54","alt":["54 cm³"],"ex":"Area of the front face = 18 cm² (split into two rectangles). Volume = 18 × 3 = 54 cm³.","units":"cm³","fig":"Lshape.svg"},{"id":"m204","topic":17,"unit":4,"day":5,"form":"num","q":"This solid is made from cuboids. Find its surface area.","a":"102","alt":["102 cm²"],"ex":"Front + back = 2 × 18 = 36. The other faces form a strip as long as the perimeter of the front (= 22 cm) and 3 cm wide: 22 × 3 = 66. Total = 36 + 66 = 102 cm².","units":"cm²","fig":"Lshape.svg"},{"id":"m205","topic":17,"unit":4,"day":5,"form":"num","q":"This solid is made from cuboids. Find its volume.","a":"144","alt":["144 cm³"],"ex":"Area of the front face = 36 cm² (split into two rectangles). Volume = 36 × 4 = 144 cm³.","units":"cm³","fig":"step.svg"},{"id":"m206","topic":17,"unit":4,"day":5,"form":"num","q":"This solid is made from cuboids. Find its surface area.","a":"184","alt":["184 cm²"],"ex":"Front + back = 2 × 36 = 72. The other faces form a strip as long as the perimeter of the front (= 28 cm) and 4 cm wide: 28 × 4 = 112. Total = 72 + 112 = 184 cm².","units":"cm²","fig":"step.svg"},{"id":"m207","topic":17,"unit":4,"day":5,"form":"num","q":"This solid is made from cuboids. Find its volume.","a":"40","alt":["40 cm³"],"ex":"Area of the front face = 20 cm² (split into two rectangles). Volume = 20 × 2 = 40 cm³.","units":"cm³","fig":"Tshape.svg"},{"id":"m208","topic":17,"unit":4,"day":5,"form":"num","q":"This solid is made from cuboids. Find its surface area.","a":"88","alt":["88 cm²"],"ex":"Front + back = 2 × 20 = 40. The other faces form a strip as long as the perimeter of the front (= 24 cm) and 2 cm wide: 24 × 2 = 48. Total = 40 + 48 = 88 cm².","units":"cm²","fig":"Tshape.svg"},{"id":"m209","topic":17,"unit":4,"day":5,"form":"num","q":"Two cubes of edge 3 cm are glued together face to face. Find the surface area of the new solid.","a":"90","alt":["90 cm²"],"ex":"It is a 6 × 3 × 3 cuboid: 2(18 + 18 + 9) = 90 cm². (Or: 12 faces of 9 cm² minus the 2 hidden faces: 10 × 9 = 90.)","units":"cm²"},{"id":"m210","topic":17,"unit":4,"day":5,"form":"num","q":"Four 1 cm cubes are joined in a row. Find the surface area.","a":"18","alt":["18 cm²"],"ex":"A 4 × 1 × 1 cuboid: 2(4 + 4 + 1) = 18 cm².","units":"cm²"},{"id":"m211","topic":18,"unit":4,"day":5,"form":"num","q":"Convert 3500 cm³ to litres.","a":"3.5","alt":[],"ex":"3500 ÷ 1000 = 3.5 litres."},{"id":"m212","topic":18,"unit":4,"day":5,"form":"num","q":"Convert 2.4 litres to ml.","a":"2400","alt":[],"ex":"2.4 × 1000 = 2400 ml."},{"id":"m213","topic":18,"unit":4,"day":5,"form":"num","q":"Convert 750 ml to cm³.","a":"750","alt":[],"ex":"1 ml = 1 cm³, so 750 cm³."},{"id":"m214","topic":18,"unit":4,"day":5,"form":"num","q":"Convert 250 cm³ to litres.","a":"0.25","alt":[],"ex":"250 ÷ 1000 = 0.25 litres."},{"id":"m215","topic":18,"unit":4,"day":5,"form":"num","q":"Convert 45 000 cm³ to litres.","a":"45","alt":[],"ex":"45 000 ÷ 1000 = 45 litres."},{"id":"m216","topic":18,"unit":4,"day":5,"form":"num","q":"Convert 4 m³ to litres.","a":"4000","alt":[],"ex":"4 × 1000 = 4000 litres."},{"id":"m217","topic":18,"unit":4,"day":5,"form":"num","q":"Convert 0.5 m³ to cm³.","a":"500000","alt":["500 000"],"ex":"0.5 × 1 000 000 = 500 000 cm³."},{"id":"m218","topic":18,"unit":4,"day":5,"form":"num","q":"Convert 6000 litres to m³.","a":"6","alt":[],"ex":"6000 ÷ 1000 = 6 m³."},{"id":"m219","topic":18,"unit":4,"day":5,"form":"num","q":"Convert 1.25 m³ to litres.","a":"1250","alt":[],"ex":"1.25 × 1000 = 1250 litres."},{"id":"m220","topic":19,"unit":4,"day":5,"form":"num","q":"A fish tank is 50 cm long, 30 cm wide and 40 cm high. How many litres of water does it hold when full?","a":"60","alt":["60 litres"],"ex":"V = 50 × 30 × 40 = 60 000 cm³ = 60 000 ÷ 1000 = 60 litres.","units":"litres"},{"id":"m221","topic":19,"unit":4,"day":5,"form":"num","q":"A tank 60 cm by 40 cm by 25 cm is filled with water to a depth of 20 cm. How many litres of water are in it?","a":"48","alt":["48 litres"],"ex":"Water is a cuboid 60 × 40 × 20 = 48 000 cm³ = 48 litres. (The 25 cm height is not needed.)","units":"litres"},{"id":"m222","topic":19,"unit":4,"day":5,"form":"num","q":"A juice carton is 6 cm by 4 cm by 10 cm. How many cartons are needed to fill a 1.2 litre jug?","a":"5","alt":[],"ex":"Carton = 240 cm³ = 240 ml; 1.2 l = 1200 ml; 1200 ÷ 240 = 5 cartons."},{"id":"m223","topic":19,"unit":4,"day":5,"form":"num","q":"A box 10 cm by 6 cm by 4 cm is packed with 2 cm cubes. How many cubes fit exactly?","a":"30","alt":[],"ex":"10 ÷ 2 = 5, 6 ÷ 2 = 3, 4 ÷ 2 = 2: 5 × 3 × 2 = 30 cubes. (Check: 240 ÷ 8 = 30.)"},{"id":"m224","topic":19,"unit":4,"day":5,"form":"num","q":"A closed wooden box 50 cm by 40 cm by 30 cm is painted on every face. One tin of paint covers 2000 cm². How many tins must be bought?","a":"5","alt":[],"ex":"SA = 2(2000 + 1500 + 1200) = 9400 cm². 9400 ÷ 2000 = 4.7, so 5 tins must be bought (round UP)."},{"id":"m225","topic":19,"unit":4,"day":5,"form":"num","q":"A swimming pool is 25 m long, 10 m wide and 2 m deep. How many litres of water does it hold?","a":"500000","alt":["500 000","500000 litres"],"ex":"V = 25 × 10 × 2 = 500 m³; 500 × 1000 = 500 000 litres.","units":"litres"},{"id":"m226","topic":0,"unit":3,"day":6,"form":"expr","q":"1. Simplify 5a + 3b - 2a + b","a":"3a + 4b","alt":["3a+4b"],"ex":"B1 for 3a + 4b.","marks":1},{"id":"m227","topic":1,"unit":3,"day":6,"form":"expr","q":"2. (a) Expand 4(3x - 2)","a":"12x - 8","alt":["12x-8"],"ex":"B1 for 12x - 8.","marks":1},{"id":"m228","topic":1,"unit":3,"day":6,"form":"expr","q":"(b) Expand and simplify 2(x + 5) - 3(x - 1)","a":"-x + 13","alt":["-x+13","13 - x"],"ex":"M1 for 2x + 10 - 3x + 3 (at least 3 terms correct). A1 for 13 - x (or -x + 13).","marks":2},{"id":"m229","topic":3,"unit":3,"day":6,"form":"factor","q":"3. Factorise fully 12x^2 - 8x","a":"4x(3x - 2)","alt":["4x(3x-2)"],"ex":"B2 for 4x(3x - 2). B1 for a correct partial factorisation, e.g. 4(3x^2 - 2x), 2x(6x - 4) or x(12x - 8).","marks":2},{"id":"m230","topic":4,"unit":3,"day":6,"form":"factor","q":"4. Is 6x + 12 = 3(2x + 4) fully factorised? If not, factorise 6x + 12 fully.","a":"6(x + 2)","alt":["6(2 + x)","6(x+2)"],"ex":"B1 for \"No\" with a reason (2x + 4 still has a common factor 2). B1 for 6(x + 2).","marks":2},{"id":"m231","topic":11,"unit":3,"day":6,"form":"expr","q":"5. Simplify (a) x^4 × x^5","a":"x^9","alt":[],"ex":"B1 for x^9.","marks":1},{"id":"m232","topic":11,"unit":3,"day":6,"form":"expr","q":"(b) Simplify 15y^8 ÷ 3y^2","a":"5y^6","alt":[],"ex":"B1 for 5y^6.","marks":1},{"id":"m233","topic":8,"unit":3,"day":6,"form":"expr","q":"(c) Simplify (2a^3)^4","a":"16a^12","alt":[],"ex":"B2 for 16a^12. B1 for 16a^k or ka^12 (k ≠ 0).","marks":2},{"id":"m234","topic":2,"unit":3,"day":6,"form":"num","q":"6. Find the value of 3a^2 - 2b when a = -2 and b = 5.","a":"2","alt":[],"ex":"M1 for 3 × (-2)^2 - 2 × 5 or 12 - 10. A1 for 2.","marks":2},{"id":"m235","topic":6,"unit":3,"day":6,"form":"num","q":"7. v = u + at. Find t when v = 35, u = 5 and a = 6.","a":"5","alt":["t = 5"],"ex":"M1 for 35 = 5 + 6t or 6t = 30. A1 for t = 5.","marks":2},{"id":"m236","topic":10,"unit":3,"day":6,"form":"num","q":"8. The angles of a triangle are 2x, 3x and 4x. Find x.","a":"20","alt":["x = 20"],"ex":"M1 for 2x + 3x + 4x = 180 or 9x = 180. A1 for x = 20.","fig":"mocktri.svg","marks":2},{"id":"m237","topic":13,"unit":4,"day":6,"form":"num","q":"9. Find the area of this trapezium.","a":"70","alt":["70 cm²"],"ex":"M1 for ½ × (8 + 12) × 7. A1 for 70 cm².","units":"cm²","fig":"mocktrap.svg","marks":2},{"id":"m238","topic":12,"unit":4,"day":6,"form":"num","q":"10. (a) Find the area of a triangle with base 9 cm and height 6 cm.","a":"27","alt":["27 cm²"],"ex":"B1 for 27 cm².","units":"cm²","marks":1},{"id":"m239","topic":12,"unit":4,"day":6,"form":"num","q":"(b) Find the area of a parallelogram with base 11 cm and perpendicular height 4 cm.","a":"44","alt":["44 cm²"],"ex":"B1 for 44 cm².","units":"cm²","marks":1},{"id":"m240","topic":15,"unit":4,"day":6,"form":"num","q":"11. (a) For this cuboid, find its volume.","a":"72","alt":["72 cm³"],"ex":"B1 for 72 cm³.","units":"cm³","fig":"mockcub.svg","marks":1},{"id":"m241","topic":16,"unit":4,"day":6,"form":"num","q":"11. (b) For the same cuboid, find its surface area.","a":"108","alt":["108 cm²"],"ex":"M1 for 2(6×4 + 6×3 + 4×3) or at least two different correct face areas (24, 18, 12). A1 for 108 cm².","units":"cm²","fig":"mockcub.svg","marks":2},{"id":"m242","topic":18,"unit":4,"day":6,"form":"num","q":"12. A fish tank is 40 cm by 25 cm by 30 cm. How many litres does it hold?","a":"30","alt":["30 litres"],"ex":"M1 for 40 × 25 × 30 = 30 000 (cm³). A1 for 30 litres.","units":"litres","marks":2},{"id":"m243","topic":17,"unit":4,"day":6,"form":"num","q":"13. This solid is made from two cuboids. Find its surface area.","a":"94","alt":["94 cm²"],"ex":"M1 for area of front face = 23 (e.g. 7 × 2 + 3 × 3). M1 for 2 × 23 + 24 × 2 (perimeter 24 × depth 2) or adding all eight faces: 46 + 14 + 4 + 8 + 6 + 6 + 10. A1 for 94 cm².","units":"cm²","fig":"mockL.svg","marks":3},{"id":"m244","topic":1,"unit":3,"day":0,"form":"expr","q":"Expand 2(4x + 9)","a":"8x + 18","alt":["8x+18"],"ex":"Multiply every term inside the bracket by the term outside: 2 × 4x = 8x, 2 × 9 = 18. Answer: 8x + 18."},{"id":"m245","topic":1,"unit":3,"day":0,"form":"expr","q":"Expand -2(6b - 9)","a":"-12b + 18","alt":["-12b+18"],"ex":"Multiply every term inside the bracket by the term outside: -2 × 6b = -12b, -2 × (-9) = 18. Answer: -12b + 18."},{"id":"m246","topic":1,"unit":3,"day":0,"form":"expr","q":"Expand -2(5x + 4)","a":"-10x - 8","alt":["-10x-8"],"ex":"Multiply every term inside the bracket by the term outside: -2 × 5x = -10x, -2 × 4 = -8. Answer: -10x - 8."},{"id":"m247","topic":1,"unit":3,"day":0,"form":"expr","q":"Expand 2(4b + 2)","a":"8b + 4","alt":["8b+4"],"ex":"Multiply every term inside the bracket by the term outside: 2 × 4b = 8b, 2 × 2 = 4. Answer: 8b + 4."},{"id":"m248","topic":1,"unit":3,"day":0,"form":"expr","q":"Expand -3(5y - 6)","a":"-15y + 18","alt":["-15y+18"],"ex":"Multiply every term inside the bracket by the term outside: -3 × 5y = -15y, -3 × (-6) = 18. Answer: -15y + 18."},{"id":"m249","topic":1,"unit":3,"day":0,"form":"expr","q":"Expand 4(4b + 6)","a":"16b + 24","alt":["16b+24"],"ex":"Multiply every term inside the bracket by the term outside: 4 × 4b = 16b, 4 × 6 = 24. Answer: 16b + 24."},{"id":"m250","topic":1,"unit":3,"day":0,"form":"expr","q":"Expand -3(4a - 2)","a":"-12a + 6","alt":["-12a+6"],"ex":"Multiply every term inside the bracket by the term outside: -3 × 4a = -12a, -3 × (-2) = 6. Answer: -12a + 6."},{"id":"m251","topic":1,"unit":3,"day":0,"form":"expr","q":"Expand 5(3x - 5)","a":"15x - 25","alt":["15x-25"],"ex":"Multiply every term inside the bracket by the term outside: 5 × 3x = 15x, 5 × (-5) = -25. Answer: 15x - 25."},{"id":"m252","topic":3,"unit":3,"day":0,"form":"factor","q":"Factorise fully 16b^2 - 4b","a":"4b(4b - 1)","alt":["4b(4b-1)"],"ex":"HCF of the terms is 4b. Divide each term by it: 16b^2 ÷ 4b = 4b, -4b ÷ 4b = -1. Answer: 4b(4b - 1). Check: expanding gives 16b^2 - 4b."},{"id":"m253","topic":3,"unit":3,"day":0,"form":"factor","q":"Factorise fully 6b^2 + 24b","a":"6b(b + 4)","alt":["6b(4 + b)","6b(b+4)"],"ex":"HCF of the terms is 6b. Divide each term by it: 6b^2 ÷ 6b = b, 24b ÷ 6b = 4. Answer: 6b(b + 4). Check: expanding gives 6b^2 + 24b."},{"id":"m254","topic":3,"unit":3,"day":0,"form":"factor","q":"Factorise fully 24a^2 - 30a","a":"6a(4a - 5)","alt":["6a(4a-5)"],"ex":"HCF of the terms is 6a. Divide each term by it: 24a^2 ÷ 6a = 4a, -30a ÷ 6a = -5. Answer: 6a(4a - 5). Check: expanding gives 24a^2 - 30a."},{"id":"m255","topic":3,"unit":3,"day":0,"form":"factor","q":"Factorise fully 4y - 14","a":"2(2y - 7)","alt":["2(2y-7)"],"ex":"HCF of the terms is 2. Divide each term by it: 4y ÷ 2 = 2y, -14 ÷ 2 = -7. Answer: 2(2y - 7). Check: expanding gives 4y - 14."},{"id":"m256","topic":3,"unit":3,"day":0,"form":"factor","q":"Factorise fully 30x^2 + 24x","a":"6x(5x + 4)","alt":["6x(4 + 5x)","6x(5x+4)"],"ex":"HCF of the terms is 6x. Divide each term by it: 30x^2 ÷ 6x = 5x, 24x ÷ 6x = 4. Answer: 6x(5x + 4). Check: expanding gives 30x^2 + 24x."},{"id":"m257","topic":3,"unit":3,"day":0,"form":"factor","q":"Factorise fully 25a^2 - 20a","a":"5a(5a - 4)","alt":["5a(5a-4)"],"ex":"HCF of the terms is 5a. Divide each term by it: 25a^2 ÷ 5a = 5a, -20a ÷ 5a = -4. Answer: 5a(5a - 4). Check: expanding gives 25a^2 - 20a."},{"id":"m258","topic":3,"unit":3,"day":0,"form":"factor","q":"Factorise fully 9a + 3","a":"3(3a + 1)","alt":["3(1 + 3a)","3(3a+1)"],"ex":"HCF of the terms is 3. Divide each term by it: 9a ÷ 3 = 3a, 3 ÷ 3 = 1. Answer: 3(3a + 1). Check: expanding gives 9a + 3."},{"id":"m259","topic":3,"unit":3,"day":0,"form":"factor","q":"Factorise fully 30b^2 - 24b","a":"6b(5b - 4)","alt":["6b(5b-4)"],"ex":"HCF of the terms is 6b. Divide each term by it: 30b^2 ÷ 6b = 5b, -24b ÷ 6b = -4. Answer: 6b(5b - 4). Check: expanding gives 30b^2 - 24b."},{"id":"m260","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 4m^5 × 5m^5","a":"20m^10","alt":[],"ex":"Multiply the numbers: 4 × 5 = 20. Multiply the letters (same letter: add the powers): m^5 × m^5 = m^10. Answer: 20m^10."},{"id":"m261","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 5m^4 × 2m^3","a":"10m^7","alt":[],"ex":"Multiply the numbers: 5 × 2 = 10. Multiply the letters (same letter: add the powers): m^4 × m^3 = m^7. Answer: 10m^7."},{"id":"m262","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 2a^7 × 5a^6","a":"10a^13","alt":[],"ex":"Multiply the numbers: 2 × 5 = 10. Multiply the letters (same letter: add the powers): a^7 × a^6 = a^13. Answer: 10a^13."},{"id":"m263","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 5m^5 × 3m^6","a":"15m^11","alt":[],"ex":"Multiply the numbers: 5 × 3 = 15. Multiply the letters (same letter: add the powers): m^5 × m^6 = m^11. Answer: 15m^11."},{"id":"m264","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 2x^5 × 4x^3","a":"8x^8","alt":[],"ex":"Multiply the numbers: 2 × 4 = 8. Multiply the letters (same letter: add the powers): x^5 × x^3 = x^8. Answer: 8x^8."},{"id":"m265","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 3x^3 × 5x^4","a":"15x^7","alt":[],"ex":"Multiply the numbers: 3 × 5 = 15. Multiply the letters (same letter: add the powers): x^3 × x^4 = x^7. Answer: 15x^7."},{"id":"m266","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 2x^5 × 2x^5","a":"4x^10","alt":[],"ex":"Multiply the numbers: 2 × 2 = 4. Multiply the letters (same letter: add the powers): x^5 × x^5 = x^10. Answer: 4x^10."},{"id":"m267","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 6x^3 × 3x","a":"18x^4","alt":[],"ex":"Multiply the numbers: 6 × 3 = 18. Multiply the letters (same letter: add the powers): x^3 × x = x^4. Answer: 18x^4."},{"id":"m268","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 24x^9 ÷ 6x^4","a":"4x^5","alt":[],"ex":"Divide the numbers: 24 ÷ 6 = 4. Divide the letters (same letter: subtract the powers): x^9 ÷ x^4 = x^5. Answer: 4x^5."},{"id":"m269","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 35a^7b^3 ÷ 7a^2b","a":"5a^5b^2","alt":["5a^5b²"],"ex":"Divide the numbers: 35 ÷ 7 = 5. Divide the letters (same letter: subtract the powers): a^7b^3 ÷ a^2b = a^5b^2. Answer: 5a^5b^2."},{"id":"m270","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 16m^6 ÷ 8m","a":"2m^5","alt":[],"ex":"Divide the numbers: 16 ÷ 8 = 2. Divide the letters (same letter: subtract the powers): m^6 ÷ m = m^5. Answer: 2m^5."},{"id":"m271","topic":8,"unit":3,"day":0,"form":"expr","q":"Simplify 45y^10 ÷ 9y^5","a":"5y^5","alt":[],"ex":"Divide the numbers: 45 ÷ 9 = 5. Divide the letters (same letter: subtract the powers): y^10 ÷ y^5 = y^5. Answer: 5y^5."},{"id":"m272","topic":13,"unit":4,"day":0,"form":"num","q":"A trapezium has parallel sides 3 cm and 9 cm and height 4 cm. Find its area.","a":"24","alt":["24 cm²"],"ex":"½(3 + 9) × 4 = 24 cm².","units":"cm²"},{"id":"m273","topic":13,"unit":4,"day":0,"form":"num","q":"A trapezium has parallel sides 6 cm and 14 cm and height 5 cm. Find its area.","a":"50","alt":["50 cm²"],"ex":"½(6 + 14) × 5 = 50 cm².","units":"cm²"},{"id":"m274","topic":13,"unit":4,"day":0,"form":"num","q":"A trapezium has parallel sides 10 cm and 16 cm and height 7 cm. Find its area.","a":"91","alt":["91 cm²"],"ex":"½(10 + 16) × 7 = 91 cm².","units":"cm²"},{"id":"m275","topic":13,"unit":4,"day":0,"form":"num","q":"A trapezium has parallel sides 4.5 cm and 7.5 cm and height 6 cm. Find its area.","a":"36","alt":["36 cm²"],"ex":"½(4.5 + 7.5) × 6 = 36 cm².","units":"cm²"},{"id":"m276","topic":15,"unit":4,"day":0,"form":"num","q":"Find the volume and then the surface area of a cuboid 9 cm by 4 cm by 3 cm. Give the VOLUME.","a":"108","alt":["108 cm³"],"ex":"V = 9 × 4 × 3 = 108 cm³.","units":"cm³"},{"id":"m277","topic":15,"unit":4,"day":0,"form":"num","q":"Find the surface area of a cuboid 9 cm by 4 cm by 3 cm.","a":"150","alt":["150 cm²"],"ex":"2(36 + 27 + 12) = 150 cm².","units":"cm²"},{"id":"m278","topic":15,"unit":4,"day":0,"form":"num","q":"Find the volume and then the surface area of a cuboid 11 cm by 5 cm by 2 cm. Give the VOLUME.","a":"110","alt":["110 cm³"],"ex":"V = 11 × 5 × 2 = 110 cm³.","units":"cm³"},{"id":"m279","topic":15,"unit":4,"day":0,"form":"num","q":"Find the surface area of a cuboid 11 cm by 5 cm by 2 cm.","a":"174","alt":["174 cm²"],"ex":"2(55 + 22 + 10) = 174 cm².","units":"cm²"},{"id":"m280","topic":15,"unit":4,"day":0,"form":"num","q":"Find the volume and then the surface area of a cuboid 7 cm by 7 cm by 7 cm. Give the VOLUME.","a":"343","alt":["343 cm³"],"ex":"V = 7 × 7 × 7 = 343 cm³.","units":"cm³"},{"id":"m281","topic":15,"unit":4,"day":0,"form":"num","q":"Find the surface area of a cuboid 7 cm by 7 cm by 7 cm.","a":"294","alt":["294 cm²"],"ex":"2(49 + 49 + 49) = 294 cm².","units":"cm²"},{"id":"m282","topic":15,"unit":4,"day":0,"form":"num","q":"Find the volume and then the surface area of a cuboid 15 cm by 4 cm by 6 cm. Give the VOLUME.","a":"360","alt":["360 cm³"],"ex":"V = 15 × 4 × 6 = 360 cm³.","units":"cm³"},{"id":"m283","topic":15,"unit":4,"day":0,"form":"num","q":"Find the surface area of a cuboid 15 cm by 4 cm by 6 cm.","a":"348","alt":["348 cm²"],"ex":"2(60 + 90 + 24) = 348 cm².","units":"cm²"},{"id":"m284","topic":18,"unit":4,"day":0,"form":"num","q":"Convert 8200 cm³ to litres.","a":"8.2","alt":[],"ex":"8200 ÷ 1000 = 8.2 litres."},{"id":"m285","topic":18,"unit":4,"day":0,"form":"num","q":"Convert 3 m³ to litres.","a":"3000","alt":[],"ex":"3 × 1000 = 3000 litres."},{"id":"m286","topic":18,"unit":4,"day":0,"form":"num","q":"Convert 0.75 litres to cm³.","a":"750","alt":[],"ex":"0.75 × 1000 = 750 cm³."},{"id":"m287","topic":18,"unit":4,"day":0,"form":"num","q":"Convert 2 m³ to cm³.","a":"2000000","alt":["2 000 000"],"ex":"2 × 1 000 000 = 2 000 000 cm³."}]};
